CREATE TABLE `catalogo_productos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `categoria_id` int(11) DEFAULT NULL COMMENT 'FK -> catalogo_categorias.id',
  `codigo` varchar(50) DEFAULT NULL,
  `nombre` varchar(500) NOT NULL,
  `sustancia` text DEFAULT NULL,
  `precio_empresa` decimal(10,2) DEFAULT 0.00,
  `precio_farmacia` decimal(10,2) DEFAULT 0.00,
  `precio_distribuidor` decimal(10,2) DEFAULT 0.00,
  `precio_red_fria` decimal(10,2) DEFAULT 0.00,
  `orden` int(11) DEFAULT 0,
  `tipo` varchar(50) DEFAULT 'SECO',
  `imagen` varchar(255) DEFAULT 'PENDIENTE',
  `solo_empresa` varchar(2) DEFAULT 'NO',
  `en_promocion` tinyint(1) NOT NULL DEFAULT 0,
  `descuento_porcentaje` decimal(5,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `promocion_perfil` varchar(50) NOT NULL DEFAULT 'TODOS',
  `tasa_iva` decimal(5,2) DEFAULT 0.00,
  `visibilidad` varchar(50) NOT NULL DEFAULT 'TODOS',
  PRIMARY KEY (`id`),
  KEY `idx_categoria` (`categoria_id`),
  CONSTRAINT `fk_producto_categoria` FOREIGN KEY (`categoria_id`) REFERENCES `catalogo_categorias` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=926 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
